def run(batch,oracle_path,submit):
 spec=importlib.util.spec_from_file_location('batch_oracles',oracle_path);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
 entries={e['global_number']:e for e in json.loads(Path('collab/gmyhf-pending-triage.json').read_text())['entries']};catalog=json.loads(Path('data/openjudge/catalog.json').read_text())['problems'];output=Path(f'/tmp/gmyhf-batch{batch}-audit.json')
 if output.exists():result=json.loads(output.read_text());result['selfchecks']=m.selfcheck()
 else:result={'batch':batch,'baseline':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'started_at':now(),'entries':[],'scope':'只读复核与公开参考源码提交；不改平台测试、不激活数据或改valid()','sources':{p:sha(p) for p in ['judge.py','data/openjudge/catalog.json','data/openjudge/limits.json','collab/gmyhf-pending-triage.json']},'selfchecks':m.selfcheck()}
 session=oj_submit.Session().login();anonymous=oj_submit.Session()
 for n in m.NUMBERS:
  if any(r['global_number']==n and r.get('complete') and (not submit or 'platform' in r['checks']) for r in result['entries']):continue
  e=entries[n];base=Path('data/openjudge/tests/admin_download')/str(n)
  snapshot=json.loads(Path('data/openjudge/tests/admin_download/manifest.json').read_text())['problems'][str(n)];files={f['filename']:f for f in snapshot['files']};records=[]
