   if name.endswith('.in'):
    out=name[:-3]+'.out';assert out in files;records.append({'input':name,'output':out,'input_sha256':files[name]['sha256'],'output_sha256':files[out]['sha256']})
  assert len(records)*2==len(files)
  candidates=list(Path('data/openjudge/tests').glob(f'*/{n}_made/samplecode.*'));ref=Path(e['made_reference']) if e.get('made_reference') else next(p for p in candidates if p.suffix=='.cpp');language='cpp' if ref.suffix=='.cpp' else 'python3';validator=ref.with_name('producecase.py');page=Path(f'data/openjudge/pages/practice__{n}.html');row=next((r for r in result['entries'] if r['global_number']==n),None)
