    assert r.returncode==0,(n,'validator execution failed');bad=json.loads(r.stdout);text=validator.read_text();node=next(x for x in ast.parse(text).body if isinstance(x,ast.FunctionDef) and x.name=='valid');c['contract']={'cases':len(records),'rejected':bad,'definition':ast.get_source_segment(text,node)};write(output,result)
   if hasattr(m,'contract_diagnostic') and 'contract_diagnostic' not in c:
    with tempfile.TemporaryDirectory(prefix='pending-contract-trace-') as work:r=subprocess.run([sys.executable,'/tmp/gmyhf_contract_diagnostic_driver.py',str(validator.resolve()),str(base.resolve()),str(n)],cwd=work,capture_output=True,text=True,timeout=120)
    assert r.returncode==0,(n,'contract diagnostic failed');c['contract_diagnostic']=json.loads(r.stdout);write(output,result)
   if hasattr(m,'extra_contract') and 'extra_contract' not in c:
    c['extra_contract']={'definition':'按解码题面补足原valid未覆盖的语义范围；实现见独立复算器extra_contract','files':[{'input':r['input'],'issues':m.extra_contract(n,(base/r['input']).read_text(encoding='utf-8-sig'))} for r in records]};write(output,result)
   if hasattr(m,'decoded') and 'decoded_statement' not in c:
    c['decoded_statement']={'sha256':hashlib.sha256(m.decoded(n).encode()).hexdigest(),'procedure':'只对HTML数据节点或固定字符串做Base64及gzip解码，不执行JS'};write(output,result)
   if 'answers' not in c:
    samples=m.samples(n);assert samples or n in getattr(m,'NO_SAMPLES',{}),(n,'no samples')
    for given,want in samples:assert ((m.eight_certificate(given,m.SOLVERS[n](given)) and m.eight_certificate(given,want)) if n==27150 else getattr(m,'compare',lambda n,a,b:a.split()==b.split())(n,m.SOLVERS[n](given),want)),(n,'sample mismatch')
    checks=[]
    for r in records:
     started=time.monotonic();got=m.SOLVERS[n]((base/r['input']).read_text(encoding='utf-8-sig'));want=(base/r['output']).read_text(encoding='utf-8-sig');checks.append({**r,'matches':(m.eight_certificate((base/r['input']).read_text(),got) and m.eight_certificate((base/r['input']).read_text(),want)) if n==27150 else getattr(m,'compare',lambda n,a,b:a.split()==b.split())(n,got,want),'oracle_ms':round((time.monotonic()-started)*1000)})
    c['answers']={'method':m.METHODS[n],'official_samples':len(samples),'files':checks};write(output,result)
   if 'local' not in c:
    item=copy.deepcopy(next(p for p in catalog if p.get('book')=='practice' and p.get('id')==str(n)));item['test_cases']=[{'input':str((base/r['input']).resolve()),'output':str((base/r['output']).resolve())} for r in records]
    with patch.object(judge,'catalog_item',return_value=item):c['local']=judge.judge('practice',str(n),language,ref.read_text(),collect_case_times=True)
    write(output,result)
   if not c['statement'].get('available',True):c['platform']={'final':'Not submitted','attempts':[],'reason':m.UNAVAILABLE_NO_SUBMISSION[n]}
   if submit and 'platform' not in c:
    attempts=row.setdefault('platform_attempts',[])
    for language in (('G++',) if ref.suffix=='.cpp' else ('Python3','PyPy3')):
     prior=next((a for a in attempts if a['language']==language),None)
     if prior is None:
      sid=session.submit(str(n),ref.read_text(),language);prior={'language':language,'solution_id':sid,'url':oj_submit.HOST+f'/practice/solution/{sid}/'};attempts.append(prior);write(output,result)
     if 'verdict' not in prior:prior.update(session.poll(prior['solution_id']));write(output,result)
